(2554420, 353323, 21714, '<td valign="top">Serves him right! :)</td>', 'Serves him right! :)', '2006-06-26 10:32:28.000000', NULL, 1),
(2554423, 353215, 21714, '<td valign="top">Great timing. A magical shot.</td>', 'Great timing. A magical shot.', '2006-06-26 10:33:42.000000', NULL, 1),
(2554449, 353297, 32254, '<td valign="top">Funny, nice job</td>', 'Funny, nice job', '2006-06-26 10:49:04.000000', NULL, 1),
(2554452, 353323, 32254, '<td valign="top">Whoa!! haha great shot</td>', 'Whoa!! haha great shot', '2006-06-26 10:50:06.000000', NULL, 1),
(2554473, 352311, 55061, '<td valign="top">nice idea! and nice image!</td>', 'nice idea! and nice image!', '2006-06-26 10:59:12.000000', NULL, 1),
(2554476, 353332, 55061, '<td valign="top">a bit to blurry but nice idea</td>', 'a bit to blurry but nice idea', '2006-06-26 11:01:20.000000', NULL, 1),
(2554477, 353153, 51538, '<td valign="top">Like the differential speed exhibited in the shot and the front/back subjects.  Nice tones makes for simple easy viewing. 9.</td>', 'Like the differential speed exhibited in the shot and the front/back subjects.  Nice tones makes for simple easy viewing. 9.', '2006-06-26 11:01:46.000000', NULL, 1),
(2554479, 353219, 51538, '<td valign="top">Like the dramatic black and the fortuitous way in which the taxi is outlines in the lighter part of the background.  Nice London image. 8.</td>', 'Like the dramatic black and the fortuitous way in which the taxi is outlines in the lighter part of the background.  Nice London image. 8.', '2006-06-26 11:02:39.000000', NULL, 1),
(2554480, 351746, 51538, '<td valign="top">Nice action there, good colour too.  Works well for the summer feeling! 8.</td>', 'Nice action there, good colour too.  Works well for the summer feeling! 8.', '2006-06-26 11:03:07.000000', NULL, 1),
(2554481, 352738, 51538, '<td valign="top">Suble and gentle by flowing-water-photo standards.  Like the mossy rock which makes the picture. 8.</td>', 'Suble and gentle by flowing-water-photo standards.  Like the mossy rock which makes the picture. 8.', '2006-06-26 11:03:41.000000', NULL, 1),
(2554482, 353423, 55061, '<td valign="top">to blurry</td>', 'to blurry', '2006-06-26 11:03:45.000000', NULL, 1),
(2554484, 353613, 51538, '<td valign="top">Nice movement and the colours all work well. 7.</td>', 'Nice movement and the colours all work well. 7.', '2006-06-26 11:04:13.000000', NULL, 1),
