(2555191, 352740, 42100, '<td valign="top">Very nice action photo.  Great color and composition.  Don''t know much about horses but I bet this guy is top of the line.</td>', 'Very nice action photo.  Great color and composition.  Don''t know much about horses but I bet this guy is top of the line.', '2006-06-26 15:16:29.000000', NULL, 1),
(2555192, 353305, 58840, '<td valign="top">so the cucumbers WERE injured in the making of this picture?!?</td>', 'so the cucumbers WERE injured in the making of this picture?!?', '2006-06-26 15:16:55.000000', NULL, 1),
