INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2555196, 353137, 30049, '<td valign="top">Very nice motion panning here.  Left the empty space in front - good.  The downhill angle works very nice to put a diagonal line pop in.  Should do well with this one.  Good luck!</td>', 'Very nice motion panning here.  Left the empty space in front - good.  The downhill angle works very nice to put a diagonal line pop in.  Should do well with this one.  Good luck!', '2006-06-26 15:18:33.000000', NULL, 1),
(2555202, 352378, 30049, '<td valign="top">This is cool.  Looks to have been done in PP?  Perhaps you have a cool zoom lens.  ;^)  Nice treatment of colors and contrast.  Good luck.</td>', 'This is cool.  Looks to have been done in PP?  Perhaps you have a cool zoom lens.  ;^)  Nice treatment of colors and contrast.  Good luck.', '2006-06-26 15:20:14.000000', NULL, 1),
(2555208, 350203, 30049, '<td valign="top">Best of the pool table shots I''ve seen thus far.  Nice action with the balls, yet the shooters hand and arm are relatively stopped.  I know the green is probably represented as is, but I would have tried to darken it just a bit if possible to make it a little richer.  Just a thought.  ;^)  Good luck in the challenge.</td>', 'Best of the pool table shots I''ve seen thus far.  Nice action with the balls, yet the shooters hand and arm are relatively stopped.  I know the green is probably represented as is, but I would have tried to darken it just a bit if possible to make it a little richer.  Just a thought.  ;^)  Good luck in the challenge.', '2006-06-26 15:22:11.000000', NULL, 1),
(2555210, 353569, 58840, '<td valign="top">wow, he is cookin''!</td>', 'wow, he is cookin''!', '2006-06-26 15:22:46.000000', NULL, 1),
(2555221, 353413, 30049, '<td valign="top">This looks to be a nice scenic spot.  Somehow this image seems a little dark, like it might be underexposed a little (which is pretty amazing for a waterfall shot - usually they''re overexposed).  Could just be a gloomy overcast day.  While this is an interesting shot I''m not overly excited about it for the challenge.  It probably fits, but the subject is not as exciting as others I''ve seen presented thus far.  Good luck in the challenge.<br/> <br/>Smile and keep having fun!  ;^)</td>', 'This looks to be a nice scenic spot.  Somehow this image seems a little dark, like it might be underexposed a little (which is pretty amazing for a waterfall shot - usually they''re overexposed).  Could just be a gloomy overcast day.  While this is an interesting shot I''m not overly excited about it for the challenge.  It probably fits, but the subject is not as exciting as others I''ve seen presented thus far.  Good luck in the challenge. Smile and keep having fun!  ;^)', '2006-06-26 15:26:11.000000', NULL, 1),
(2555223, 353520, 58840, '<td valign="top">cool concept.  thanx for a new technique!  10!</td>', 'cool concept.  thanx for a new technique!  10!', '2006-06-26 15:26:35.000000', NULL, 1),
(2555230, 353362, 58840, '<td valign="top">that''s ambition!</td>', 'that''s ambition!', '2006-06-26 15:27:27.000000', NULL, 1),
(2555232, 352659, 30049, '<td valign="top">Hard to get a slow shutter speed with action like this isn''t it?  ;^)  I like the sense of motion portrayed here.  The bright colors help sell the story.  Good luck.</td>', 'Hard to get a slow shutter speed with action like this isn''t it?  ;^)  I like the sense of motion portrayed here.  The bright colors help sell the story.  Good luck.', '2006-06-26 15:27:49.000000', NULL, 1),
(2555234, 351895, 58840, '<td valign="top">cool!  how many weird looks and comments did you get while shooting this?  lol!</td>', 'cool!  how many weird looks and comments did you get while shooting this?  lol!', '2006-06-26 15:28:12.000000', NULL, 1),
(2555235, 352731, 31133, '<td valign="top">This is a nice image. I''m drawn to the person''s hat ... really good focal point with that little tassle on top!</td>', 'This is a nice image. I''m drawn to the person''s hat ... really good focal point with that little tassle on top!', '2006-06-26 15:28:13.000000', NULL, 1),
(2555238, 353663, 58840, '<td valign="top">ummmmm, no.  where''s the motion  blur?  hwere''s it''s face even?</td>', 'ummmmm, no.  where''s the motion  blur?  hwere''s it''s face even?', '2006-06-26 15:29:09.000000', NULL, 1),
(2555239, 353655, 40973, '<td valign="top">.<br/><br/><i>Message edited by author 2006-08-17 11:08:55.</i></td>', '.', '2006-06-26 15:29:12.000000', '2006-08-17 12:08:55.000000', 1),
(2555240, 353741, 42100, '<td valign="top">Very clever idea for the challenge.  Good look of frustration from your model.  Well done!</td>', 'Very clever idea for the challenge.  Good look of frustration from your model.  Well done!', '2006-06-26 15:29:15.000000', NULL, 1),
(2555241, 353215, 30049, '<td valign="top">Looks like the fawn is flying!  Very nice job of motion panning to catch the action the way you have.  You also did well leaving empty space out front for the deer to "move into".  The vignetting is a little obvious, but not sure how it could have been done much differently.  Good luck.<br/> <br/>Smile and keep having fun!  ;^)</td>', 'Looks like the fawn is flying!  Very nice job of motion panning to catch the action the way you have.  You also did well leaving empty space out front for the deer to "move into".  The vignetting is a little obvious, but not sure how it could have been done much differently.  Good luck. Smile and keep having fun!  ;^)', '2006-06-26 15:29:33.000000', NULL, 1),
(2555242, 352378, 31133, '<td valign="top">Woweeee - this is amazing!</td>', 'Woweeee - this is amazing!', '2006-06-26 15:29:34.000000', NULL, 1),
(2555248, 353614, 31133, '<td valign="top">Look at those arms! What a wonderful shot and title. The water is silky smooth.</td>', 'Look at those arms! What a wonderful shot and title. The water is silky smooth.', '2006-06-26 15:30:46.000000', NULL, 1),
(2555250, 353314, 42100, '<td valign="top">Like the composition and duotone treatment.  This looks like something right out of a 1940''s Hollywood production.  Very nice!</td>', 'Like the composition and duotone treatment.  This looks like something right out of a 1940''s Hollywood production.  Very nice!', '2006-06-26 15:31:04.000000', NULL, 1),
(2555254, 353404, 30049, '<td valign="top">This is a pretty image.  The waterfall is placed nicely within the overall composition with the water flowing down and thru the image.  Too bad you couldn''t have gotten a more dramatic sky for this shoot.  Not that it''s anything you could have controlled - just an observation.  As for the subject, yes I guess it fits the challenge technically - but it''s not quite as exciting as some other subjects I''ve seen in the challenge with a bit more action.  This is kind of static.<br/> <br/>Best of luck to you in the challenge.</td>', 'This is a pretty image.  The waterfall is placed nicely within the overall composition with the water flowing down and thru the image.  Too bad you couldn''t have gotten a more dramatic sky for this shoot.  Not that it''s anything you could have controlled - just an observation.  As for the subject, yes I guess it fits the challenge technically - but it''s not quite as exciting as some other subjects I''ve seen in the challenge with a bit more action.  This is kind of static. Best of luck to you in the challenge.', '2006-06-26 15:32:12.000000', NULL, 1),
(2555255, 353263, 42100, '<td valign="top">Interesting looking ferris wheel.  Good strong dynamic composition.  Well done!</td>', 'Interesting looking ferris wheel.  Good strong dynamic composition.  Well done!', '2006-06-26 15:32:22.000000', NULL, 1),
(2555257, 353591, 58840, '<td valign="top">great d&amp;b.  love the yellow saturation.  10!</td>', 'great d&b.  love the yellow saturation.  10!', '2006-06-26 15:32:27.000000', NULL, 1),
(2555262, 353743, 30049, '<td valign="top">This is nice.  I really like the tones with the white/grey horse and the matching background.  Hope this does well for you.  Good luck.</td>', 'This is nice.  I really like the tones with the white/grey horse and the matching background.  Hope this does well for you.  Good luck.', '2006-06-26 15:33:18.000000', NULL, 1),
(2555265, 353591, 31133, '<td valign="top">Beautiful!! What a ghost-like image. Great processing to boot.</td>', 'Beautiful!! What a ghost-like image. Great processing to boot.', '2006-06-26 15:33:46.000000', NULL, 1),
(2555267, 353297, 58840, '<td valign="top">LOL!  awesome.</td>', 'LOL!  awesome.', '2006-06-26 15:34:40.000000', NULL, 1),
(2555268, 352984, 42100, '<td valign="top">A frozen moment of time in the life of a city...very good mix of still and blur.  The bright taxi really makes this photo leap out at you.  Well done!</td>', 'A frozen moment of time in the life of a city...very good mix of still and blur.  The bright taxi really makes this photo leap out at you.  Well done!', '2006-06-26 15:34:47.000000', NULL, 1),
(2555272, 352738, 30049, '<td valign="top">Hey.  This would of worked for the ''Green II'' challenge recently.  ;^)  Very pretty place - very tranquil, peaceful.  Having said that, while I like this image I''m not feeling a good sense of action, blurred motion, that is being presented in other images in this challenge.  Nothing personal...it''s a nice shot - just not very "exciting" as a subject.  Best of luck to you.</td>', 'Hey.  This would of worked for the ''Green II'' challenge recently.  ;^)  Very pretty place - very tranquil, peaceful.  Having said that, while I like this image I''m not feeling a good sense of action, blurred motion, that is being presented in other images in this challenge.  Nothing personal...it''s a nice shot - just not very "exciting" as a subject.  Best of luck to you.', '2006-06-26 15:35:58.000000', NULL, 1),
(2555302, 352882, 42100, '<td valign="top">Well captured motion blur, but it seems rather distant and doesn''t make much of a statement.  Zooming in on one of the horses or riders could offer a little more for the viewer to interact with.</td>', 'Well captured motion blur, but it seems rather distant and doesn''t make much of a statement.  Zooming in on one of the horses or riders could offer a little more for the viewer to interact with.', '2006-06-26 15:48:46.000000', NULL, 1),
(2555312, 350223, 42100, '<td valign="top">There are some interesting dynamics going on with the blur of the bug.  But the composition seems rather stagnent and too centered.  Maybe a tighter and off centered crop would make the subject a little stronger.</td>', 'There are some interesting dynamics going on with the blur of the bug.  But the composition seems rather stagnent and too centered.  Maybe a tighter and off centered crop would make the subject a little stronger.', '2006-06-26 15:51:18.000000', NULL, 1),
(2555321, 353625, 42100, '<td valign="top">A strong and dynamic composition.  Red and blue makes a bold statement against the white background.  But the motion blur is at an absolute minimum and borderline non-existent.</td>', 'A strong and dynamic composition.  Red and blue makes a bold statement against the white background.  But the motion blur is at an absolute minimum and borderline non-existent.', '2006-06-26 15:54:06.000000', NULL, 1),
(2555322, 353054, 42100, '<td valign="top">There are some interesting motion blur going on here.  There just isn''t a strong enough focal point for my tastes.  If there was some sort of pattern or rhythm it would be a much stronger photo.</td>', 'There are some interesting motion blur going on here.  There just isn''t a strong enough focal point for my tastes.  If there was some sort of pattern or rhythm it would be a much stronger photo.', '2006-06-26 15:54:13.000000', NULL, 1),
