(2556611, 353297, 59335, '<td valign="top">Really cool idea!  I also like how you placed yourself right in the middle of the action although some of your shorter characters got lost behind you.  But, is that the remote shutter release in your hand? :-p</td>', 'Really cool idea!  I also like how you placed yourself right in the middle of the action although some of your shorter characters got lost behind you.  But, is that the remote shutter release in your hand? :-p', '2006-06-27 00:33:11.000000', NULL, 1),
(2556722, 353569, 24983, '<td valign="top">good one this really meets the challenge</td>', 'good one this really meets the challenge', '2006-06-27 01:07:32.000000', NULL, 1),
(2556727, 351544, 24983, '<td valign="top">the light fills the frame well</td>', 'the light fills the frame well', '2006-06-27 01:08:29.000000', NULL, 1),
