INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2557440, 351943, 35078, '<td valign="top">Very nice shot. Ribbon for sure! 10</td>', 'Very nice shot. Ribbon for sure! 10', '2006-06-27 08:09:34.000000', NULL, 1),
(2557442, 353393, 35078, '<td valign="top">Very well done!</td>', 'Very well done!', '2006-06-27 08:12:00.000000', NULL, 1),
(2557450, 353440, 58665, '<td valign="top">Great capture, you really sense the frantic motion of the wings, yet you have managed to keep sharp focus on the eye.  Well done an 8 from me.</td>', 'Great capture, you really sense the frantic motion of the wings, yet you have managed to keep sharp focus on the eye.  Well done an 8 from me.', '2006-06-27 08:32:45.000000', NULL, 1),
(2557451, 353742, 58665, '<td valign="top">Fantastic shot, great composition, fantastic lighting and awesome sharpness. You get an 8, well done, oh buggar it you get a 9.  I really love this shot.</td>', 'Fantastic shot, great composition, fantastic lighting and awesome sharpness. You get an 8, well done, oh buggar it you get a 9.  I really love this shot.', '2006-06-27 08:32:59.000000', NULL, 1),
(2557458, 353137, 22561, '<td valign="top">This to me is what a motion blur photo is all about. The subject caught crisply, well positioned within the image, and the background not distractingly busy, with the sensation of speed. Well done!</td>', 'This to me is what a motion blur photo is all about. The subject caught crisply, well positioned within the image, and the background not distractingly busy, with the sensation of speed. Well done!', '2006-06-27 08:44:37.000000', NULL, 1),
(2557460, 353308, 58665, '<td valign="top">The idea for this shot is fantastic, and so is the capture of the motion, my only critique is that the lighting is not great, which might effect your score.  Also the feet on the bar stool in the top right hand corner should have been cloned out, as they are distracting.</td>', 'The idea for this shot is fantastic, and so is the capture of the motion, my only critique is that the lighting is not great, which might effect your score.  Also the feet on the bar stool in the top right hand corner should have been cloned out, as they are distracting.', '2006-06-27 08:45:45.000000', NULL, 1),
(2557462, 352846, 22561, '<td valign="top">Well done. I''d like to see a little more space to the left.</td>', 'Well done. I''d like to see a little more space to the left.', '2006-06-27 08:46:34.000000', NULL, 1),
(2557495, 353514, 1531, '<td valign="top">Glæsilegt skot, vel gert</td>', 'Glæsilegt skot, vel gert', '2006-06-27 09:06:24.000000', NULL, 1),
(2557497, 353137, 1531, '<td valign="top">nice composition, I like how the tilt increases the feel of speed</td>', 'nice composition, I like how the tilt increases the feel of speed', '2006-06-27 09:07:49.000000', NULL, 1),
(2557524, 353297, 55040, '<td valign="top">Haha... this is great! Very creative and well portrayed!</td>', 'Haha... this is great! Very creative and well portrayed!', '2006-06-27 09:31:28.000000', NULL, 1),
(2557528, 353591, 30049, '<td valign="top">I like your choice of location for this shot.  The angle it gives you works well.  The yellow works well with the surrounding bleakness.  Did you consider doing a desat on this to make the yellow pop even more?  Good luck in the challenge.</td>', 'I like your choice of location for this shot.  The angle it gives you works well.  The yellow works well with the surrounding bleakness.  Did you consider doing a desat on this to make the yellow pop even more?  Good luck in the challenge.', '2006-06-27 09:35:59.000000', NULL, 1),
(2557532, 353329, 30049, '<td valign="top">This works well with the stationary subject and the moving players.  Enough blur to show motion, but not so much you lose the entire player forms.  Only complaint I have (it''s minor) is the position you selected to take this from.  The background left is distracting.  A few steps to your left maybe?  Just a thought.  Good luck in the challenge.</td>', 'This works well with the stationary subject and the moving players.  Enough blur to show motion, but not so much you lose the entire player forms.  Only complaint I have (it''s minor) is the position you selected to take this from.  The background left is distracting.  A few steps to your left maybe?  Just a thought.  Good luck in the challenge.', '2006-06-27 09:38:25.000000', NULL, 1),
(2557535, 352883, 30049, '<td valign="top">Sorry, but I''m missing something here.  What''s the subject, and what''s moving?  Where''s the blur?</td>', 'Sorry, but I''m missing something here.  What''s the subject, and what''s moving?  Where''s the blur?', '2006-06-27 09:39:31.000000', NULL, 1),
(2557536, 353614, 30049, '<td valign="top">Here''s a water shot that works.  ;^)  It has a subject!  I imagine you had fun getting this image taken.  Well, maybe the boy had more fun.  He-he.  Good idea.  Best of luck in the challenge.</td>', 'Here''s a water shot that works.  ;^)  It has a subject!  I imagine you had fun getting this image taken.  Well, maybe the boy had more fun.  He-he.  Good idea.  Best of luck in the challenge.', '2006-06-27 09:40:51.000000', NULL, 1),
(2557539, 352512, 30049, '<td valign="top">Very pretty, and nice scenic shot.  Feels quite serene and quiet.  Not what I envision at first thinking of ''Motion Blur''.  Yes, I guess it meets the challenge and it is a nice image - however, against other more exciting action type shots...<br/> <br/>No worries.  I''m not voting.  Just making observations.  ;^)  Good luck in the challenge.</td>', 'Very pretty, and nice scenic shot.  Feels quite serene and quiet.  Not what I envision at first thinking of ''Motion Blur''.  Yes, I guess it meets the challenge and it is a nice image - however, against other more exciting action type shots... No worries.  I''m not voting.  Just making observations.  ;^)  Good luck in the challenge.', '2006-06-27 09:43:42.000000', NULL, 1),
(2557541, 352338, 35804, '<td valign="top">Vintage fan on a hot summer day...excellent shot...love the tone and clarity.</td>', 'Vintage fan on a hot summer day...excellent shot...love the tone and clarity.', '2006-06-27 09:45:53.000000', NULL, 1),
(2557543, 353351, 30049, '<td valign="top">Nice capture in the manner of something fun to look at.  I''m thinking either you had some problems sizing it for the challenge, or you did a major crop from a larger image...as posted, there is some substantial pixelation going on.  More regarding the subject - I don''t think there''s really enough "Motion" in this shot.  The only "Blur" is in the engine prop.  Perhaps a motion panning approach for this may have been a little stronger?</td>', 'Nice capture in the manner of something fun to look at.  I''m thinking either you had some problems sizing it for the challenge, or you did a major crop from a larger image...as posted, there is some substantial pixelation going on.  More regarding the subject - I don''t think there''s really enough "Motion" in this shot.  The only "Blur" is in the engine prop.  Perhaps a motion panning approach for this may have been a little stronger?', '2006-06-27 09:47:21.000000', NULL, 1),
(2557545, 353406, 60187, '<td valign="top">Excellent moment!</td>', 'Excellent moment!', '2006-06-27 09:48:28.000000', NULL, 1),
(2557546, 353198, 51538, '<td valign="top">Love the colours, like the abstract nature of the image, but have not got a clue as to how to vote on this with regard to the subject being motion blur.  So, for the time being, am only leaving a comment, no vote.  I might come back later and edit and leave a vote. == OK, came back.  I am hitting the vote button.  The image colours and design are far too rich to ignore. 9.</td>', 'Love the colours, like the abstract nature of the image, but have not got a clue as to how to vote on this with regard to the subject being motion blur.  So, for the time being, am only leaving a comment, no vote.  I might come back later and edit and leave a vote. == OK, came back.  I am hitting the vote button.  The image colours and design are far too rich to ignore. 9.', '2006-06-27 09:49:26.000000', NULL, 1),
(2557548, 352486, 30049, '<td valign="top">Very peaceful, serene image.  Not getting much connection to "Motion Blur" however.  I mean, yes, technically motion blur exists here, but it''s not quite evident with the length of exposure you used.  Too smooth and foggy in the final result.  JMO.  Good luck in the challenge.</td>', 'Very peaceful, serene image.  Not getting much connection to "Motion Blur" however.  I mean, yes, technically motion blur exists here, but it''s not quite evident with the length of exposure you used.  Too smooth and foggy in the final result.  JMO.  Good luck in the challenge.', '2006-06-27 09:50:37.000000', NULL, 1),
(2557549, 353409, 51538, '<td valign="top">Nice lads shot.  Simple but effective and timely too.</td>', 'Nice lads shot.  Simple but effective and timely too.', '2006-06-27 09:50:41.000000', NULL, 1),
(2557551, 352731, 51538, '<td valign="top">This zoom really does take one down the alleyway.</td>', 'This zoom really does take one down the alleyway.', '2006-06-27 09:51:03.000000', NULL, 1),
(2557555, 353614, 51538, '<td valign="top">Beautiful location.  Imagine it must be pretty dark for a long exposue.  Getting children to do what one wants is not always easy, is it ;-)  Would have preferred less of the dragonfly wings and more of the dancing...</td>', 'Beautiful location.  Imagine it must be pretty dark for a long exposue.  Getting children to do what one wants is not always easy, is it ;-)  Would have preferred less of the dragonfly wings and more of the dancing...', '2006-06-27 09:52:21.000000', NULL, 1),
(2557558, 353296, 30049, '<td valign="top">Appropriately titled.  ;^)  Very ghostly type feel to this image.  I like it overall.  Doesn''t appear that the keys are really moving very much however.  Look at the shadows - they seem quite defined and don''t seem to have moved as much as the key blur would indicate.  Interesting effect.  Good luck in the challenge.</td>', 'Appropriately titled.  ;^)  Very ghostly type feel to this image.  I like it overall.  Doesn''t appear that the keys are really moving very much however.  Look at the shadows - they seem quite defined and don''t seem to have moved as much as the key blur would indicate.  Interesting effect.  Good luck in the challenge.', '2006-06-27 09:52:54.000000', NULL, 1),
(2557559, 351489, 51538, '<td valign="top">Mystical effect, right!  Would be better without the lamp post.</td>', 'Mystical effect, right!  Would be better without the lamp post.', '2006-06-27 09:52:58.000000', NULL, 1),
(2557562, 353154, 51538, '<td valign="top">This is an interesting image.  I like it a lot.  I wish the characters (Jiu Jia), the big ones up top, were more centered.  The window blinds are very effective.  Worth doing again to work out the kinks.</td>', 'This is an interesting image.  I like it a lot.  I wish the characters (Jiu Jia), the big ones up top, were more centered.  The window blinds are very effective.  Worth doing again to work out the kinks.', '2006-06-27 09:54:47.000000', NULL, 1),
(2557563, 353304, 51538, '<td valign="top">That elephant has a Mohican haircut!  Nice informative shot and the motion is subtle but effective. 6.</td>', 'That elephant has a Mohican haircut!  Nice informative shot and the motion is subtle but effective. 6.', '2006-06-27 09:55:26.000000', NULL, 1),
(2557564, 353423, 51538, '<td valign="top">Great idea.  I think the exposure is a bit too long.  But the effect is interesting and happy.</td>', 'Great idea.  I think the exposure is a bit too long.  But the effect is interesting and happy.', '2006-06-27 09:56:16.000000', NULL, 1),
(2557566, 352722, 51538, '<td valign="top">Aquarium shots are not easy.  This is pretty decent.  Mine are far worse.  Including one of my <a href="//www.advancelit.com/img/javatank.jpg" rel="nofollow" target="_blank">aquarium gardens</a>.</td>', 'Aquarium shots are not easy.  This is pretty decent.  Mine are far worse.  Including one of my aquarium gardens.', '2006-06-27 09:58:51.000000', NULL, 1),
(2557571, 353267, 51538, '<td valign="top">The focused geometric juxtaposed with the blurred chaotic.  Great effect.  Nice subtle colours in the water too.  The boat part is not quite boat enough, if you know what I mean.  But, no doubt, this was not an easy shot to compose.</td>', 'The focused geometric juxtaposed with the blurred chaotic.  Great effect.  Nice subtle colours in the water too.  The boat part is not quite boat enough, if you know what I mean.  But, no doubt, this was not an easy shot to compose.', '2006-06-27 10:01:42.000000', NULL, 1),
(2557572, 353734, 51538, '<td valign="top">Always was better at the right-handers myself.  Nice crisp focus.</td>', 'Always was better at the right-handers myself.  Nice crisp focus.', '2006-06-27 10:02:30.000000', NULL, 1),
(2557575, 353446, 51538, '<td valign="top">The beachcombing figures enhances this photo.  Nice breezy day!</td>', 'The beachcombing figures enhances this photo.  Nice breezy day!', '2006-06-27 10:03:24.000000', NULL, 1),
(2557617, 352846, 52939, '<td valign="top">nice crop, nice detail.  good luck.</td>', 'nice crop, nice detail.  good luck.', '2006-06-27 10:37:20.000000', NULL, 1),
(2557639, 351489, 30049, '<td valign="top">Ahhh...took me a minute.  The title is what did it for me.  Wonder what this would look like if you did a desat on all but yellow and red?  This has an abstract feel to it.  Certainly is ''Motion Blur''!  ;^)  Good luck in the challenge.</td>', 'Ahhh...took me a minute.  The title is what did it for me.  Wonder what this would look like if you did a desat on all but yellow and red?  This has an abstract feel to it.  Certainly is ''Motion Blur''!  ;^)  Good luck in the challenge.', '2006-06-27 10:51:08.000000', NULL, 1),
(2557642, 353515, 30049, '<td valign="top">This almost looks like a toy setup.  At first, from the thumbnail, I thought it was.  Looks like an interesting event to have witnessed.  This image does a nice job of meeting the challenge for ''Motion Blur''.  Well done.  I''ll bet you had some issues trying to figure how to adjust, if at all, the composition to get the main subject off-center.  Crop in front of the horse and you lose empty space for the subject to move into.  Crop behind the horse and lose the cool dust trail.  ;^)<br/> <br/>Smile and keep having fun!</td>', 'This almost looks like a toy setup.  At first, from the thumbnail, I thought it was.  Looks like an interesting event to have witnessed.  This image does a nice job of meeting the challenge for ''Motion Blur''.  Well done.  I''ll bet you had some issues trying to figure how to adjust, if at all, the composition to get the main subject off-center.  Crop in front of the horse and you lose empty space for the subject to move into.  Crop behind the horse and lose the cool dust trail.  ;^) Smile and keep having fun!', '2006-06-27 10:54:58.000000', NULL, 1),
(2557647, 353704, 30049, '<td valign="top">It''s a nice shot.  Composed well, exposed correctly, etc...  Bit of a clich''e perhaps when one thinks of a motion blur shot.  Hope you had fun at the event.  Best of luck in the challenge.</td>', 'It''s a nice shot.  Composed well, exposed correctly, etc...  Bit of a clich''e perhaps when one thinks of a motion blur shot.  Hope you had fun at the event.  Best of luck in the challenge.', '2006-06-27 10:58:22.000000', NULL, 1),
(2557650, 353249, 30049, '<td valign="top">Where''s the kayaker''s?!  This would have been really cool with a brightly colored kayaker coming thru the course.  Not sure why you went B/W.  Looks to be slightly underexposed?  Whites aren''t really popping.  The angle is interesting.  Good luck in the challenge.</td>', 'Where''s the kayaker''s?!  This would have been really cool with a brightly colored kayaker coming thru the course.  Not sure why you went B/W.  Looks to be slightly underexposed?  Whites aren''t really popping.  The angle is interesting.  Good luck in the challenge.', '2006-06-27 11:00:15.000000', NULL, 1),
(2557652, 350223, 30049, '<td valign="top">Yep.  It''s a blurry bug alright.  ;^)  Perhaps if you could have gotten the background closer to true white and off-centered the subject a little more?</td>', 'Yep.  It''s a blurry bug alright.  ;^)  Perhaps if you could have gotten the background closer to true white and off-centered the subject a little more?', '2006-06-27 11:01:25.000000', NULL, 1),
(2557665, 351039, 30049, '<td valign="top">Hmmm.  Not sure what you were attempting to do here.  The pole appears blurred, like you were in a car or on a train and moving past this scene.  Unfortunately, the main subject seems to be the boat - and it''s not moving.  It''s anchored.  ;^)  I also find the background trees to be distracting.  Did you consider cropping this down to just below the shoreline and bring it in a bit from the right as well?  Just a thought.<br/> <br/>No worries.  I''m not voting, only observing.  Good luck in the challenge.</td>', 'Hmmm.  Not sure what you were attempting to do here.  The pole appears blurred, like you were in a car or on a train and moving past this scene.  Unfortunately, the main subject seems to be the boat - and it''s not moving.  It''s anchored.  ;^)  I also find the background trees to be distracting.  Did you consider cropping this down to just below the shoreline and bring it in a bit from the right as well?  Just a thought. No worries.  I''m not voting, only observing.  Good luck in the challenge.', '2006-06-27 11:05:32.000000', NULL, 1),
(2557668, 353708, 30049, '<td valign="top">Nice, soothing abstract feel.  I like it.  Good luck.</td>', 'Nice, soothing abstract feel.  I like it.  Good luck.', '2006-06-27 11:06:11.000000', NULL, 1),
(2557677, 353642, 30049, '<td valign="top">This is a bit extreme.  I kind of like it, although it may be a bit outside the DPChallenge comfort zone.  Most likely you are getting comments like "the sky is blown out", "green color cast", etc...<br/> <br/>Personally, nice choice of artistic take on the challenge.  Good sense of movement and rhythm.  Best of luck to you in the challenge.</td>', 'This is a bit extreme.  I kind of like it, although it may be a bit outside the DPChallenge comfort zone.  Most likely you are getting comments like "the sky is blown out", "green color cast", etc... Personally, nice choice of artistic take on the challenge.  Good sense of movement and rhythm.  Best of luck to you in the challenge.', '2006-06-27 11:09:11.000000', NULL, 1),
(2557682, 351272, 30049, '<td valign="top">Looks like fireworks!  ;^)  Appropriately titled.  You did a nice job with exposure on this.  Nearly blown out on the whites in the center of the crashing wave.  I like the early/late day sunlight on the rocks and the shadows the light creates.  I haven''t decided if the ship in the background adds or takes away from this image.  No matter...<br/> <br/>Good luck in the challenge.</td>', 'Looks like fireworks!  ;^)  Appropriately titled.  You did a nice job with exposure on this.  Nearly blown out on the whites in the center of the crashing wave.  I like the early/late day sunlight on the rocks and the shadows the light creates.  I haven''t decided if the ship in the background adds or takes away from this image.  No matter... Good luck in the challenge.', '2006-06-27 11:12:20.000000', NULL, 1),
(2557687, 353365, 30049, '<td valign="top">It''s "ok".  This may have had more impact if the subject flower wasn''t centered.  You have some negative dark space on the right that could have been cropped out.  Just a thought.   Good luck.</td>', 'It''s "ok".  This may have had more impact if the subject flower wasn''t centered.  You have some negative dark space on the right that could have been cropped out.  Just a thought.   Good luck.', '2006-06-27 11:14:19.000000', NULL, 1),
