(2564960, 353410, 37893, '<td valign="top">Motion captured well here. The desat reminds me of one of my shots for the Green Challenge. The sharpness of the tree serves itself as the main subject of this image. Nicely done desat. Great job :)</td>', 'Motion captured well here. The desat reminds me of one of my shots for the Green Challenge. The sharpness of the tree serves itself as the main subject of this image. Nicely done desat. Great job :)', '2006-06-29 03:01:40.000000', NULL, 1),
(2565065, 353520, 39484, '<td valign="top">This is really interesting and will surely get dpc''er riled up.  10</td>', 'This is really interesting and will surely get dpc''er riled up.  10', '2006-06-29 03:26:46.000000', NULL, 1),
(2565068, 353406, 39484, '<td valign="top">This image has a wonderful old world feel.  Very nicely composed. 10</td>', 'This image has a wonderful old world feel.  Very nicely composed. 10', '2006-06-29 03:27:46.000000', NULL, 1),
(2565071, 353219, 39484, '<td valign="top">This is fantastic,  Great use of negative space on top, making the car look tiny, 10</td>', 'This is fantastic,  Great use of negative space on top, making the car look tiny, 10', '2006-06-29 03:28:40.000000', NULL, 1),
(2565087, 353283, 39484, '<td valign="top">when I was doing research about motion blur, a book suggested that you shoot with a busy background so the blur can be seen.  Here, it is hard to get a good read on the speed because there is no contrast in the background.  Also, it is sort of standard to have more negative space in front of a subject''s implied line of motion.  In other words, the motorcycle should be driving into empty space rather than off the frame.  That is a classical rule. (don''t have to follow it of course,)<br/>Good work. 6</td>', 'when I was doing research about motion blur, a book suggested that you shoot with a busy background so the blur can be seen.  Here, it is hard to get a good read on the speed because there is no contrast in the background.  Also, it is sort of standard to have more negative space in front of a subject''s implied line of motion.  In other words, the motorcycle should be driving into empty space rather than off the frame.  That is a classical rule. (don''t have to follow it of course,)Good work. 6', '2006-06-29 03:33:35.000000', NULL, 1),
(2565097, 353741, 39484, '<td valign="top">Fun concept.  Make sure you white balance the wall so everything doesn''t have a yellow cast. <br/>Good job,</td>', 'Fun concept.  Make sure you white balance the wall so everything doesn''t have a yellow cast. Good job,', '2006-06-29 03:36:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2565103, 353751, 39484, '<td valign="top">nice abstract piece.  I''m afraid the voters will not be kind, but don''t worry.  I wish more people would submit stuff like this,</td>', 'nice abstract piece.  I''m afraid the voters will not be kind, but don''t worry.  I wish more people would submit stuff like this,', '2006-06-29 03:38:32.000000', NULL, 1),
(2565104, 353154, 39484, '<td valign="top">great job, 10.</td>', 'great job, 10.', '2006-06-29 03:39:35.000000', NULL, 1),
(2565109, 353380, 39484, '<td valign="top">The color cast is a bit overwhelming.  play around with selective color in ps or raw conversion, and this would really pop.</td>', 'The color cast is a bit overwhelming.  play around with selective color in ps or raw conversion, and this would really pop.', '2006-06-29 03:41:35.000000', NULL, 1),
(2565115, 353218, 39484, '<td valign="top">I love this.  Very painterly.</td>', 'I love this.  Very painterly.', '2006-06-29 03:42:58.000000', NULL, 1),
(2565121, 353384, 39484, '<td valign="top">It was great that you had the guts to include the signs.  It really adds narrative.  If this doesn''t ribbon, it is because the motion is not as prominent graphically as the other elements.  Great job. 9</td>', 'It was great that you had the guts to include the signs.  It really adds narrative.  If this doesn''t ribbon, it is because the motion is not as prominent graphically as the other elements.  Great job. 9', '2006-06-29 03:46:20.000000', NULL, 1),
(2565127, 353447, 39484, '<td valign="top">Great image and composition.</td>', 'Great image and composition.', '2006-06-29 03:49:35.000000', NULL, 1),
(2565129, 350223, 39484, '<td valign="top">10.</td>', '10.', '2006-06-29 03:50:33.000000', NULL, 1),
(2565130, 353514, 39484, '<td valign="top">Great ad shot.</td>', 'Great ad shot.', '2006-06-29 03:51:35.000000', NULL, 1),
(2565136, 353616, 39484, '<td valign="top">Classically speaking, there should be more negative space for the subject to move into rather than drive away from.</td>', 'Classically speaking, there should be more negative space for the subject to move into rather than drive away from.', '2006-06-29 03:54:55.000000', NULL, 1),
(2565252, 353348, 61199, '<td valign="top">Yikes!</td>', 'Yikes!', '2006-06-29 05:32:25.000000', NULL, 1),
(2565325, 353409, 25890, '<td valign="top">You pretty much nailed the panning part, and exposure seems ok even if a little bit underexposed. However composition/crop is too tight and, combined with the straight-on angle, effectively kills the sense of motion one expects to find in this type of photographs despite the presence of back-/foreground blur.</td>', 'You pretty much nailed the panning part, and exposure seems ok even if a little bit underexposed. However composition/crop is too tight and, combined with the straight-on angle, effectively kills the sense of motion one expects to find in this type of photographs despite the presence of back-/foreground blur.', '2006-06-29 06:40:45.000000', NULL, 1),
(2565330, 353735, 25890, '<td valign="top">Even though the photograph is technically good enough, it seems as if there were an interesting story to be told about this person and the environment but it''d been left out somewhere outside the frame. That''s to say that the picture is somewhat incomplete, in my opinion. I wonder if a wider angle of view wouldn''t have helped capture that story better. Additionally, the motion blur, i.e. the blurred people around the person, appears to be more like an unavoidable result of having to use a slow shutter speed than a deliberate attempt at setting a certain mood.</td>', 'Even though the photograph is technically good enough, it seems as if there were an interesting story to be told about this person and the environment but it''d been left out somewhere outside the frame. That''s to say that the picture is somewhat incomplete, in my opinion. I wonder if a wider angle of view wouldn''t have helped capture that story better. Additionally, the motion blur, i.e. the blurred people around the person, appears to be more like an unavoidable result of having to use a slow shutter speed than a deliberate attempt at setting a certain mood.', '2006-06-29 06:59:51.000000', NULL, 1),
(2565613, 353215, 48235, '<td valign="top">deer missile</td>', 'deer missile', '2006-06-29 09:43:56.000000', NULL, 1),
(2565676, 353614, 32378, '<td valign="top">Nice rich colors, good composition I think the boy adds to this shot.</td>', 'Nice rich colors, good composition I think the boy adds to this shot.', '2006-06-29 10:37:19.000000', NULL, 1),
(2565678, 353218, 32378, '<td valign="top">This may not do well with the voters, but I like it.</td>', 'This may not do well with the voters, but I like it.', '2006-06-29 10:37:52.000000', NULL, 1),
(2565697, 352512, 32378, '<td valign="top">This is a nice shot, but the border on this really seems to interfere with the composition. IMO</td>', 'This is a nice shot, but the border on this really seems to interfere with the composition. IMO', '2006-06-29 10:48:02.000000', NULL, 1),
(2565983, 353735, 50695, '<td valign="top">nice use of motion blur to emphasize and even comment on your subject.</td>', 'nice use of motion blur to emphasize and even comment on your subject.', '2006-06-29 12:10:08.000000', NULL, 1),
(2565992, 353413, 50695, '<td valign="top">the waterfall going over skewed rocks, plus an interesting foreground, makes this distinctive.</td>', 'the waterfall going over skewed rocks, plus an interesting foreground, makes this distinctive.', '2006-06-29 12:12:15.000000', NULL, 1),
(2565997, 353153, 50695, '<td valign="top">the background, which is not only blurred but blown, gives a sense of not just motion but a certain ecstasy that motorcycles must provide, or why else would anyone ride such a dangerous beast?</td>', 'the background, which is not only blurred but blown, gives a sense of not just motion but a certain ecstasy that motorcycles must provide, or why else would anyone ride such a dangerous beast?', '2006-06-29 12:14:09.000000', NULL, 1),
(2566001, 352902, 50695, '<td valign="top">remarkable capture, double entendre intended. the only motion blur is the bird''s head, and it is this motion that undoes the frog. a day in the death of a frog.</td>', 'remarkable capture, double entendre intended. the only motion blur is the bird''s head, and it is this motion that undoes the frog. a day in the death of a frog.', '2006-06-29 12:15:46.000000', NULL, 1),
(2566002, 352850, 50695, '<td valign="top">great colors, the motion blur conveys joy.</td>', 'great colors, the motion blur conveys joy.', '2006-06-29 12:16:39.000000', NULL, 1),
(2566006, 353306, 50695, '<td valign="top">a wonderful, daring blur creates a tangible mood of excitement.</td>', 'a wonderful, daring blur creates a tangible mood of excitement.', '2006-06-29 12:18:55.000000', NULL, 1),
(2566023, 352882, 50695, '<td valign="top">great concept, with the center not as blurred as the edges, plus childhood memory is a great subject for blur. Next time upload a bigger picture, though. 7</td>', 'great concept, with the center not as blurred as the edges, plus childhood memory is a great subject for blur. Next time upload a bigger picture, though. 7', '2006-06-29 12:26:26.000000', NULL, 1),
(2566036, 349735, 50695, '<td valign="top">pretty! appropriate subject for a zoom blur.</td>', 'pretty! appropriate subject for a zoom blur.', '2006-06-29 12:32:00.000000', NULL, 1),
(2566042, 353397, 50695, '<td valign="top">great effect, but I find the doubled left foot disturbing.</td>', 'great effect, but I find the doubled left foot disturbing.', '2006-06-29 12:33:51.000000', NULL, 1),
(2566045, 353323, 50695, '<td valign="top">nice effect, plus an extra point for funny = 7</td>', 'nice effect, plus an extra point for funny = 7', '2006-06-29 12:35:30.000000', NULL, 1),
(2566094, 353708, 50695, '<td valign="top">looks like brush strokes. nicely done.</td>', 'looks like brush strokes. nicely done.', '2006-06-29 12:49:09.000000', NULL, 1),
(2566098, 353625, 50695, '<td valign="top">great! all it needs is some motion blur! 7</td>', 'great! all it needs is some motion blur! 7', '2006-06-29 12:49:54.000000', NULL, 1),
(2566100, 353583, 50695, '<td valign="top">mystical effect</td>', 'mystical effect', '2006-06-29 12:50:34.000000', NULL, 1),
