(2566145, 353348, 50695, '<td valign="top">7 for funny. nicely executed illusion</td>', '7 for funny. nicely executed illusion', '2006-06-29 13:03:46.000000', NULL, 1),
(2566162, 352736, 50695, '<td valign="top">reminiscent of nude descending a staircase. you took a chance and it worked.</td>', 'reminiscent of nude descending a staircase. you took a chance and it worked.', '2006-06-29 13:07:25.000000', NULL, 1),
(2566165, 353663, 50695, '<td valign="top">6 points just for being so weird.</td>', '6 points just for being so weird.', '2006-06-29 13:08:07.000000', NULL, 1),
(2566215, 352338, 50695, '<td valign="top">the straight-on angle of the fan plus the pitch black background makes the off-center composition ineffective, i.e. it has no effect except to be off center. But a great picture of a fan.</td>', 'the straight-on angle of the fan plus the pitch black background makes the off-center composition ineffective, i.e. it has no effect except to be off center. But a great picture of a fan.', '2006-06-29 13:20:36.000000', NULL, 1),
(2566243, 353616, 50695, '<td valign="top">boring subject but great blur!</td>', 'boring subject but great blur!', '2006-06-29 13:33:54.000000', NULL, 1),
(2566247, 353517, 50695, '<td valign="top">great idea to curve the path of the coin. I think I want even more of a curve.</td>', 'great idea to curve the path of the coin. I think I want even more of a curve.', '2006-06-29 13:35:11.000000', NULL, 1),
