(2575137, 351942, 55621, '<td valign="top">I don''t understand the title, but I like the overall effect.</td>', 'I don''t understand the title, but I like the overall effect.', '2006-07-02 17:31:21.000000', NULL, 1),
(2575139, 353218, 3214, '<td valign="top">Like the feel of this one, indeed impressionistic!</td>', 'Like the feel of this one, indeed impressionistic!', '2006-07-02 17:33:48.000000', NULL, 1),
(2575144, 353005, 3214, '<td valign="top">Very nicely done, love the texture in the road from the blur!</td>', 'Very nicely done, love the texture in the road from the blur!', '2006-07-02 17:34:16.000000', NULL, 1),
(2575147, 353496, 3837, '<td valign="top">Beautiful capture of the animal''s expression, and everything else is blur in the spirit of the challenge.</td>', 'Beautiful capture of the animal''s expression, and everything else is blur in the spirit of the challenge.', '2006-07-02 17:36:45.000000', NULL, 1),
