(2575155, 353332, 3837, '<td valign="top">Simplicity at its best.  The subtle colors blend and work well in this challenge that you execute to a "T".</td>', 'Simplicity at its best.  The subtle colors blend and work well in this challenge that you execute to a "T".', '2006-07-02 17:40:06.000000', NULL, 1),
(2575161, 352659, 3214, '<td valign="top">I like the subject, cropping, blur, am unbothered by the blown highlights in the water.  The tones seem less appealing, like they need to be "defogged".</td>', 'I like the subject, cropping, blur, am unbothered by the blown highlights in the water.  The tones seem less appealing, like they need to be "defogged".', '2006-07-02 17:42:53.000000', NULL, 1),
(2575162, 353161, 3837, '<td valign="top">Very attractive and conveys the scene well.</td>', 'Very attractive and conveys the scene well.', '2006-07-02 17:43:26.000000', NULL, 1),
(2575174, 351323, 3214, '<td valign="top">Is this a motion blur of a guitar string?  I would have titled it differently. ;-)</td>', 'Is this a motion blur of a guitar string?  I would have titled it differently. ;-)', '2006-07-02 17:45:57.000000', NULL, 1),
(2575175, 352736, 3837, '<td valign="top">These motions really capture the spirit of the challenge, and I know that you will ribbon.  I like the stationary number and reflective surfaces.</td>', 'These motions really capture the spirit of the challenge, and I know that you will ribbon.  I like the stationary number and reflective surfaces.', '2006-07-02 17:46:14.000000', NULL, 1),
(2575177, 353751, 3214, '<td valign="top">Fun abstract.</td>', 'Fun abstract.', '2006-07-02 17:46:29.000000', NULL, 1),
