(2578133, 353161, 11793, '<td valign="top">nice work !!!</td>', 'nice work !!!', '2006-07-03 08:53:58.000000', NULL, 0),
(2578134, 353514, 52549, '<td valign="top">Congratulations on an excellent 4th placing. This was one of the entries where the feeling of motion really came across well and as for image quality - it suits the scene perfectly. Again, well done.</td>', 'Congratulations on an excellent 4th placing. This was one of the entries where the feeling of motion really came across well and as for image quality - it suits the scene perfectly. Again, well done.', '2006-07-03 08:54:21.000000', NULL, 0),
(2578141, 353613, 53147, '<td valign="top">Trading Post - OK, this critique will be based somewhat on your past shots for part of it. The technical aspects of this shot have improved over recent entries. The settings on your camera are right where they are supposed to be to get this shot. Perfect shutter speed and low ISO. This left you with no grain and the right amount of blur. You did a very good job at keeping on her face and allowing the rest to blur. The colors all around look nice and your postprocessing does not look heavy handed at all. You met this challenge well technically. Now beyond that, the improvements to be made would have been to catch her with a different background and maybe all of her body showing. If you had all green or plantlife and sky in the background and had cuaght her whole body I think you would have scored way high. You did really well hereand captured a light and fun shot. Again - always good to see a new pic in your top rated bar - and even better when it is one of your kids (which I guess I am assuming but she looks alot like you).</td>', 'Trading Post - OK, this critique will be based somewhat on your past shots for part of it. The technical aspects of this shot have improved over recent entries. The settings on your camera are right where they are supposed to be to get this shot. Perfect shutter speed and low ISO. This left you with no grain and the right amount of blur. You did a very good job at keeping on her face and allowing the rest to blur. The colors all around look nice and your postprocessing does not look heavy handed at all. You met this challenge well technically. Now beyond that, the improvements to be made would have been to catch her with a different background and maybe all of her body showing. If you had all green or plantlife and sky in the background and had cuaght her whole body I think you would have scored way high. You did really well hereand captured a light and fun shot. Again - always good to see a new pic in your top rated bar - and even better when it is one of your kids (which I guess I am assuming but she looks alot like you).', '2006-07-03 08:56:34.000000', NULL, 0),
(2578147, 353591, 51538, '<td valign="top">Well done on the result!  This is an enduring image.</td>', 'Well done on the result!  This is an enduring image.', '2006-07-03 09:22:43.000000', NULL, 0),
(2578158, 352736, 51538, '<td valign="top">I''m glad you stuck with your choice, despite those low voters.  This is still an excellent image.</td>', 'I''m glad you stuck with your choice, despite those low voters.  This is still an excellent image.', '2006-07-03 09:27:08.000000', NULL, 0),
(2578168, 353324, 51538, '<td valign="top">Well, I thought this might be yours.  Got that certain sense of humour.  IMO worth much more in the way of points than you got... but, such is life at DPC.</td>', 'Well, I thought this might be yours.  Got that certain sense of humour.  IMO worth much more in the way of points than you got... but, such is life at DPC.', '2006-07-03 09:31:00.000000', NULL, 0),
(2578176, 353198, 51538, '<td valign="top">IMO it was worth the experiment!  I had to come back to see what it was all about.  I like the colours a lot.  Keep up the good work and forget about the scores... ;-)</td>', 'IMO it was worth the experiment!  I had to come back to see what it was all about.  I like the colours a lot.  Keep up the good work and forget about the scores... ;-)', '2006-07-03 09:33:51.000000', NULL, 0),
