(2578452, 353297, 49652, '<td valign="top">Congrats on top 10!  Great photo, one of my favorites in the challenge.</td>', 'Congrats on top 10!  Great photo, one of my favorites in the challenge.', '2006-07-03 10:59:10.000000', NULL, 0),
(2578455, 353198, 53147, '<td valign="top">Trading Post - OK - as an abstract I think this shot works very well. Cool colors and textures. The yellow on the corner though should either be gone or have more of it. I see the little bit of it and want to see more of it. It has a contrasting look and feel to it compared to the rest of the pic. I had absolutley no clue what this was a picture of. But for the challenge it was tough to vote this high IMO. I personally felt that you needed to understand what the subject was to be able to relate to the movement. Spending more time looking at it now makes me feel that I may have scored it a bit harshly, but in the DPC voting world where you spend all of a second or two glimpsing at a shot this didnt grab me or make me want to stay to inspect it further. At voting time I thought it was not interesting or relevent as a motion blur shot. Looking at it deeper now and reading your description I can see what you were shooting for but I still think it would have done much better in an abstract challenge.</td>', 'Trading Post - OK - as an abstract I think this shot works very well. Cool colors and textures. The yellow on the corner though should either be gone or have more of it. I see the little bit of it and want to see more of it. It has a contrasting look and feel to it compared to the rest of the pic. I had absolutley no clue what this was a picture of. But for the challenge it was tough to vote this high IMO. I personally felt that you needed to understand what the subject was to be able to relate to the movement. Spending more time looking at it now makes me feel that I may have scored it a bit harshly, but in the DPC voting world where you spend all of a second or two glimpsing at a shot this didnt grab me or make me want to stay to inspect it further. At voting time I thought it was not interesting or relevent as a motion blur shot. Looking at it deeper now and reading your description I can see what you were shooting for but I still think it would have done much better in an abstract challenge.', '2006-07-03 10:59:30.000000', NULL, 0),
(2578471, 353397, 3724, '<td valign="top">fyi 9 - a favorite in this challenge.  Good work.</td>', 'fyi 9 - a favorite in this challenge.  Good work.', '2006-07-03 11:04:07.000000', NULL, 0),
